const e=[{key:"edexcel-phy-topic1",name:"Edexcel物理 · Topic 1 力与运动",description:"Forces and Motion · Edexcel IGCSE 物理 · 41 个术语定义",words:[{word:"Acceleration",phonetic:"",meaning:"The rate of change of velocity. It can be calculated from the gradient of a velocity-time graph.",example:"加速度",image_url:"",emoji:"⚡"},{word:"Balanced Forces",phonetic:"",meaning:"A resultant force of zero.",example:"平衡力",image_url:"",emoji:"⚡"},{word:"Braking Distance",phonetic:"",meaning:"The distance a vehicle travels under the braking force. This can be affected by adverse road and weather conditions as well as the condition of the vehicle.",example:"制动距离",image_url:"",emoji:"⚡"},{word:"Changes of Momentum",phonetic:"",meaning:"When a force acts on a moving object, or on an object that has the ability to move, a change of momentum will occur. The force is equal to the rate of change of momentum.",example:"动量变化",image_url:"",emoji:"⚡"},{word:"Conservation of Momentum",phonetic:"",meaning:"The total momentum of a system before an event is always equal to the total momentum of the system after the event.",example:"动量守恒",image_url:"",emoji:"⚡"},{word:"Contact Force",phonetic:"",meaning:"A force that acts on an object through physical contact.",example:"接触力",image_url:"",emoji:"⚡"},{word:"Crumple Zone",phonetic:"",meaning:"A vehicle safety feature that compresses during a collision. It increases the time over which the momentum change occurs, and so reduces the force experienced by the occupants.",example:"溃缩吸能区",image_url:"",emoji:"⚡"},{word:"Distance-Time Graph",phonetic:"",meaning:"A plot of how an object’s distance changes over time. The gradient of the graph at any point, equals the object’s speed at that point.",example:"距离-时间图像",image_url:"",emoji:"⚡"},{word:"Distance",phonetic:"",meaning:"A measure of how far an object moves. It doesn’t depend on direction and is therefore a scalar quantity.",example:"距离",image_url:"",emoji:"⚡"},{word:"Distortion",phonetic:"",meaning:"The changing of an object’s size or shape as a result of a deforming force.",example:"形变",image_url:"",emoji:"⚡"},{word:"Elastic Deformation",phonetic:"",meaning:"A non-permanent deformation for which the object will return to its original shape when the deforming forces are removed.",example:"弹性形变",image_url:"",emoji:"⚡"},{word:"Elastic Limit",phonetic:"",meaning:"The force beyond which an object will no longer deform elastically, and will instead deform plastically.",example:"弹性极限",image_url:"",emoji:"⚡"},{word:"Equilibrium",phonetic:"",meaning:"An object is in equilibrium if the resultant force and resultant moment are both equal to zero.",example:"平衡状态",image_url:"",emoji:"⚡"},{word:"Friction",phonetic:"",meaning:"A resistive contact force that acts to oppose the relative motion between two surfaces.",example:"摩擦力",image_url:"",emoji:"⚡"},{word:"Hooke’s Law",phonetic:"",meaning:"The extension of a spring is directly proportional to the force applied to it, up to the limit of proportionality. The constant in this relationship is known as the spring constant.",example:"胡克定律",image_url:"",emoji:"⚡"},{word:"Human Reaction Time",phonetic:"",meaning:"The time it takes for the brain to react to a stimulus. Typical human reaction times are in the range of 0.2-0.9 seconds.",example:"人类反应时间",image_url:"",emoji:"⚡"},{word:"Limit of Proportionality",phonetic:"",meaning:"The point beyond which the extension of an elastic object is no longer directly proportional to the force applied to it.",example:"比例极限",image_url:"",emoji:"⚡"},{word:"Linear Relationship",phonetic:"",meaning:"A relationship between two variables where if one variable increases, so does the other by the same factor. They produce straight lines when plotted.",example:"线性关系",image_url:"",emoji:"⚡"},{word:"Moment",phonetic:"",meaning:"The turning effect of a force, equal to the product of the magnitude of the force and the perpendicular distance from the pivot to the line of action of the force.",example:"力矩",image_url:"",emoji:"⚡"},{word:"Momentum",phonetic:"",meaning:"The product of an object’s mass and velocity.",example:"动量",image_url:"",emoji:"⚡"},{word:"Newton Meter",phonetic:"",meaning:"A device used to measure the magnitude of a force. It is commonly used to measure an object’s weight.",example:"测力计",image_url:"",emoji:"⚡"},{word:"Newton Metre",phonetic:"",meaning:"The unit of a moment.",example:"牛顿米（力矩单位）",image_url:"",emoji:"⚡"},{word:"Newton",phonetic:"",meaning:"The unit of force.",example:"牛顿",image_url:"",emoji:"⚡"},{word:"Newton’s First Law",phonetic:"",meaning:"If a stationary object’s resultant force is zero, the object will remain stationary. If a moving object’s resultant force is zero, the object will continue to move at a constant velocity (same speed and direction).",example:"牛顿第一定律",image_url:"",emoji:"⚡"},{word:"Newton’s Second Law",phonetic:"",meaning:"An object’s acceleration is directly proportional to the resultant force acting on it, and inversely proportional to the object’s mass.",example:"牛顿第二定律",image_url:"",emoji:"⚡"},{word:"Newton’s Third Law",phonetic:"",meaning:"The forces that two objects exert on each other when they interact are equal and opposite.",example:"牛顿第三定律",image_url:"",emoji:"⚡"},{word:"Non-Contact Force",phonetic:"",meaning:"A force that acts on an object at a distance. There is no physical contact, and instead the force acts through a field.",example:"非接触力",image_url:"",emoji:"⚡"},{word:"Plastic Deformation",phonetic:"",meaning:"A permanent deformation for which the object will no longer return to its original shape when the deforming forces are removed.",example:"塑性形变",image_url:"",emoji:"⚡"},{word:"Principle of Moments",phonetic:"",meaning:"For an object in equilibrium, the sum of the clockwise moments about any point on the object must equal the anticlockwise moments about that same point.",example:"力矩原理",image_url:"",emoji:"⚡"},{word:"Resultant Force",phonetic:"",meaning:"The single force that can replace all the individual forces acting on an object, and have the same effect.",example:"合力",image_url:"",emoji:"⚡"},{word:"Resultant Moment",phonetic:"",meaning:"The single moment that has the same effect as the sum of all the other clockwise and anticlockwise moments acting on an object.",example:"合力矩",image_url:"",emoji:"⚡"},{word:"Scalar Quantities",phonetic:"",meaning:"Quantities that only have a magnitude, not a direction.",example:"标量",image_url:"",emoji:"⚡"},{word:"Seat Belt",phonetic:"",meaning:"A vehicle safety device that increases the time over which the momentum change occurs during a collision, and so reduces the force experienced by the wearer.",example:"安全带",image_url:"",emoji:"⚡"},{word:"Spring Constant",phonetic:"",meaning:"A measure of a spring’s stiffness. The higher the spring constant, the smaller the extension is for a given force.",example:"弹簧劲度系数",image_url:"",emoji:"⚡"},{word:"Stopping Distance",phonetic:"",meaning:"The sum of the thinking and braking distances.",example:"停车距离",image_url:"",emoji:"⚡"},{word:"Terminal Velocity",phonetic:"",meaning:"The maximum velocity an object can reach when falling through a fluid. It occurs when the resistive forces equal the object’s weight.",example:"终端速度",image_url:"",emoji:"⚡"},{word:"Thinking Distance",phonetic:"",meaning:"The distance a vehicle travels during the driver’s reaction time. This reaction time may be affected by tiredness, drugs or alcohol.",example:"反应距离",image_url:"",emoji:"⚡"},{word:"Vector Quantities",phonetic:"",meaning:"Quantities that have both a magnitude and direction. They are represented by an arrow, with the length representing the magnitude and the arrowhead representing the direction.",example:"矢量",image_url:"",emoji:"⚡"},{word:"Velocity-Time Graph",phonetic:"",meaning:"A plot of how an object’s velocity changes over time. The gradient at any point, equals the object’s acceleration at that point. The area under the graph equals the object’s displacement.",example:"速度-时间图像",image_url:"",emoji:"⚡"},{word:"Velocity",phonetic:"",meaning:"A vector quantity that is a measure of the rate of change of displacement. It is the speed in a given direction.",example:"速度",image_url:"",emoji:"⚡"},{word:"Weight",phonetic:"",meaning:"The force acting on an object due to gravity. It is equal to the product of the object’s mass and the gravitational field strength at its location.",example:"重力",image_url:"",emoji:"⚡"}]},{key:"edexcel-phy-topic2",name:"Edexcel物理 · Topic 2 电学",description:"Electricity · Edexcel IGCSE 物理 · 40 个术语定义",words:[{word:"Alternating Current",phonetic:"",meaning:"Current flow consisting of charges that continually change direction. These oscillations usually occur at a set frequency.",example:"交流电",image_url:"",emoji:"⚡"},{word:"Ammeter",phonetic:"",meaning:"A device connected in series with a component to measure the current that flows through it.",example:"电流表",image_url:"",emoji:"⚡"},{word:"Ampere (Amp)",phonetic:"",meaning:"The unit of current.",example:"安培",image_url:"",emoji:"⚡"},{word:"Circuit Breaker",phonetic:"",meaning:"A safety device that cuts off the power supply if a surge of current passes through it. Circuit breakers can be reset and are quicker acting than fuses.",example:"断路器",image_url:"",emoji:"⚡"},{word:"Conductor",phonetic:"",meaning:"A material that allows electrical charge to flow easily. Metals are particularly good conductors due to the free electrons in their structures.",example:"导体",image_url:"",emoji:"⚡"},{word:"Coulomb",phonetic:"",meaning:"The unit of charge.",example:"库仑",image_url:"",emoji:"⚡"},{word:"Currents at a Junction",phonetic:"",meaning:"The sum of the currents entering a junction must always equal the sum of the currents leaving it. This is a consequence of the conservation of charge.",example:"节点电流",image_url:"",emoji:"⚡"},{word:"Diode",phonetic:"",meaning:"A component that only allows current to flow through in the forward direction. They have very large resistances in the reverse direction.",example:"二极管",image_url:"",emoji:"⚡"},{word:"Direct Current",phonetic:"",meaning:"Current flow consisting of charges flowing in a single direction only. Batteries and cells provide direct current.",example:"直流电",image_url:"",emoji:"⚡"},{word:"Earthing",phonetic:"",meaning:"The removal of excess charge by providing a low resistance path for electrons to flow through.",example:"接地",image_url:"",emoji:"⚡"},{word:"Earth Wire",phonetic:"",meaning:"The green and yellow striped safety wire connected to metal casings, that prevents an appliance from becoming live.",example:"地线",image_url:"",emoji:"⚡"},{word:"Electric Current",phonetic:"",meaning:"The rate of flow of electrical charge. Its value is the same at any position in a single closed loop. In metals, the charges that flow are electrons.",example:"电流",image_url:"",emoji:"⚡"},{word:"Energy Transfers in Circuits",phonetic:"",meaning:"Electrical energy is transferred to thermal energy when current does work against a resistance. In metals this is a result of collisions between electrons and ions.",example:"电路中的能量转化",image_url:"",emoji:"⚡"},{word:"Filament Lamp",phonetic:"",meaning:"A light emitting component consisting of an enclosed metal filament. Its resistance increases as the filament’s temperature increases.",example:"白炽灯",image_url:"",emoji:"⚡"},{word:"Fuse",phonetic:"",meaning:"A safety device consisting of a thin metal filament that melts and cuts off the power supply if there is a surge in current. Fuses are connected to the live wire.",example:"保险丝",image_url:"",emoji:"⚡"},{word:"Insulator",phonetic:"",meaning:"A material that doesn’t allow electrical charge to flow.",example:"绝缘体",image_url:"",emoji:"⚡"},{word:"Lightning",phonetic:"",meaning:"A consequence of static charge building up in the clouds. Lightning strikes are caused by the discharge of this charge.",example:"闪电",image_url:"",emoji:"⚡"},{word:"Like Charges",phonetic:"",meaning:"When two charges of the same polarity meet, they will repel.",example:"同种电荷",image_url:"",emoji:"⚡"},{word:"Light Dependent Resistor (LDR)",phonetic:"",meaning:"A light sensitive component whose resistance decreases as its temperature increases.",example:"光敏电阻",image_url:"",emoji:"⚡"},{word:"Light Emitting Diode",phonetic:"",meaning:"A device that gives out light when a current flows through it. Current can only flow through it in one direction, and a minimum voltage must be applied across it before it illuminates.",example:"发光二极管",image_url:"",emoji:"⚡"},{word:"Live Wire",phonetic:"",meaning:"The brown coloured wire that carries the alternating current from the supply in a mains power supply.",example:"火线",image_url:"",emoji:"⚡"},{word:"Mains Electricity",phonetic:"",meaning:"An a.c supply, which in the UK has a frequency of 50Hz a value of 230V.",example:"市电",image_url:"",emoji:"⚡"},{word:"Neutral Wire",phonetic:"",meaning:"The blue coloured wire that completes the circuit in a mains power supply.",example:"零线",image_url:"",emoji:"⚡"},{word:"Ohmic Conductor",phonetic:"",meaning:"A conductor whose current flow is directly proportional to the potential difference (voltage) across it, when held at a constant temperature.",example:"欧姆导体",image_url:"",emoji:"⚡"},{word:"Ohm",phonetic:"",meaning:"The unit of resistance.",example:"欧姆",image_url:"",emoji:"⚡"},{word:"Ohm’s Law",phonetic:"",meaning:"The current flowing through an Ohmic conductor at constant temperature is directly proportional to the potential difference (voltage) across it.",example:"欧姆定律",image_url:"",emoji:"⚡"},{word:"Parallel",phonetic:"",meaning:"Components connected in parallel have the same potential difference (voltage) across each component. The total current is equal to the sum of the currents flowing through each component.",example:"并联",image_url:"",emoji:"⚡"},{word:"Potential Difference",phonetic:"",meaning:"The energy that is transferred per unit charge between two points in a circuit. It is often also called a voltage.",example:"电势差",image_url:"",emoji:"⚡"},{word:"Power",phonetic:"",meaning:"The rate at which an appliance transfers energy. For a circuit component, it is equal to the product of the current passing through it and the potential difference across it.",example:"功率",image_url:"",emoji:"⚡"},{word:"Resistance",phonetic:"",meaning:"A measure of the opposition to current flow.",example:"电阻",image_url:"",emoji:"⚡"},{word:"Resistors in Parallel",phonetic:"",meaning:"The total resistance is less than the lowest individual resistance.",example:"并联电阻",image_url:"",emoji:"⚡"},{word:"Resistors in Series",phonetic:"",meaning:"The total resistance is equal to the sum of the resistances of the individual resistors.",example:"串联电阻",image_url:"",emoji:"⚡"},{word:"Series",phonetic:"",meaning:"Components connected in series have the same current passing through each component but share the total potential difference (voltage) of the power supply.",example:"串联",image_url:"",emoji:"⚡"},{word:"Sparking",phonetic:"",meaning:"The transfer of electrons between two surfaces that have an imbalance of charges. Sparking can be particularly dangerous in locations such as petrol pumps, and so the pumps must be earthed.",example:"火花放电",image_url:"",emoji:"⚡"},{word:"Static Charge",phonetic:"",meaning:"The charge caused by an imbalance of positive and negative charges in, or on, an object’s surface. It is often caused by electrons being rubbed from one surface onto another.",example:"静电荷",image_url:"",emoji:"⚡"},{word:"Thermistor",phonetic:"",meaning:"A temperature dependent component, whose resistance increases as its temperature decreases.",example:"热敏电阻",image_url:"",emoji:"⚡"},{word:"Unlike Charges",phonetic:"",meaning:"When two charges of opposite polarities meet, they will attract.",example:"异种电荷",image_url:"",emoji:"⚡"},{word:"Volt",phonetic:"",meaning:"The unit of potential difference (voltage). One volt is equal to one joule per coulomb.",example:"伏特",image_url:"",emoji:"⚡"},{word:"Voltmeter",phonetic:"",meaning:"A device that is connected in parallel with a component to measure the potential difference (voltage) across it.",example:"电压表",image_url:"",emoji:"⚡"},{word:"Watt",phonetic:"",meaning:"The unit of power.",example:"瓦特",image_url:"",emoji:"⚡"}]},{key:"edexcel-phy-topic3",name:"Edexcel物理 · Topic 3 波",description:"Waves · Edexcel IGCSE 物理 · 41 个术语定义",words:[{word:"Amplitude",phonetic:"",meaning:"The maximum displacement of a wave from its undisturbed (equilibrium) position.",example:"振幅",image_url:"",emoji:"⚡"},{word:"Critical Angle",phonetic:"",meaning:"The angle of incidence beyond which all the wave is totally internally reflected when it meets a boundary.",example:"临界角",image_url:"",emoji:"⚡"},{word:"Doppler Effect",phonetic:"",meaning:"The change in a wave’s observed wavelength and frequency when there is relative motion between its source and an observer.",example:"多普勒效应",image_url:"",emoji:"⚡"},{word:"Diffuse Reflection",phonetic:"",meaning:"The reflection of a wave from a rough surface that results in the wave being scattered.",example:"漫反射",image_url:"",emoji:"⚡"},{word:"Electromagnetic Spectrum",phonetic:"",meaning:"A group of transverse waves that cover a large range of frequencies and wavelengths. The highest frequency waves in the spectrum are gamma-rays and the lowest are radio waves.",example:"电磁波谱",image_url:"",emoji:"⚡"},{word:"Electromagnetic Waves",phonetic:"",meaning:"Transverse waves that transfer energy from the source of the waves, to an absorber. They form a continuous spectrum of different frequencies and all travel at the same speed in a vacuum.",example:"电磁波",image_url:"",emoji:"⚡"},{word:"Frequency",phonetic:"",meaning:"The number of waves passing a given point in a second. It is the inverse of the wave’s time period.",example:"频率",image_url:"",emoji:"⚡"},{word:"Gamma Rays",phonetic:"",meaning:"High energy radiation rays used for detecting and treating cancers, and sterilising food and medical implements. They can cause cell damage and mutations.",example:"伽马射线",image_url:"",emoji:"⚡"},{word:"Hertz (Hz)",phonetic:"",meaning:"The unit of frequency.",example:"赫兹",image_url:"",emoji:"⚡"},{word:"Human Hearing",phonetic:"",meaning:"Humans can hear sounds in the frequency range of 20Hz to 20kHz.",example:"人类听觉",image_url:"",emoji:"⚡"},{word:"Infrared Radiation",phonetic:"",meaning:"A type of radiation that all objects emit and absorb. The hotter an object is, the greater the infrared radiation it emits in a given time.",example:"红外辐射",image_url:"",emoji:"⚡"},{word:"Infrared",phonetic:"",meaning:"Used for cooking food, thermal imaging and short range communications. It can cause skin burns.",example:"红外线",image_url:"",emoji:"⚡"},{word:"Law of Reflection",phonetic:"",meaning:"The angle of incidence must always equal the angle of reflection when a wave reflects.",example:"反射定律",image_url:"",emoji:"⚡"},{word:"Longitudinal Waves",phonetic:"",meaning:"Waves with oscillations that are parallel to the direction of travel/energy transfer.",example:"纵波",image_url:"",emoji:"⚡"},{word:"Loudness",phonetic:"",meaning:"A measure of the amplitude of the oscillations of a sound wave. The larger the amplitude, the louder the sound will be.",example:"响度",image_url:"",emoji:"⚡"},{word:"Microphone",phonetic:"",meaning:"A device that converts the particle oscillations of a sound wave into an electrical signal that can be analysed using an oscilloscope.",example:"麦克风",image_url:"",emoji:"⚡"},{word:"Microwaves",phonetic:"",meaning:"Used for satellite communications and for cooking food. They can cause internal heating of body cells.",example:"微波",image_url:"",emoji:"⚡"},{word:"Oscilloscope",phonetic:"",meaning:"A device used to display the waveform of a signal. It shows how the voltage of the electrical signal varies with time.",example:"示波器",image_url:"",emoji:"⚡"},{word:"Pitch",phonetic:"",meaning:"A measure of the frequency of the oscillations of a sound wave. The higher the frequency, the higher the pitch of the sound.",example:"音调",image_url:"",emoji:"⚡"},{word:"Radio Waves",phonetic:"",meaning:"Used for television and radio signals. They can be produced by oscillations in electrical circuits, or can induce these oscillations themselves.",example:"无线电波",image_url:"",emoji:"⚡"},{word:"Ray Diagram",phonetic:"",meaning:"A visual representation of the path of a wave, usually around the point where it meets a boundary. Rays are usually drawn as straight lines with an arrow pointing in their direction of travel.",example:"光路图",image_url:"",emoji:"⚡"},{word:"Real Image",phonetic:"",meaning:"An image produced by light-rays physically converging. Real images are ones that can be projected onto a screen.",example:"实像",image_url:"",emoji:"⚡"},{word:"Reflection",phonetic:"",meaning:"The bouncing back of a wave at a boundary.",example:"反射",image_url:"",emoji:"⚡"},{word:"Refraction",phonetic:"",meaning:"The changing of speed, and consequently the direction, of a wave as it changes medium. The wavelength of the wave will also change but the frequency remains constant.",example:"折射",image_url:"",emoji:"⚡"},{word:"Refractive Index",phonetic:"",meaning:"The ratio of the speed of the wave in a vacuum to the speed of the wave in a given medium.",example:"折射率",image_url:"",emoji:"⚡"},{word:"Seismic Waves",phonetic:"",meaning:"Waves that are produced by earthquakes.",example:"地震波",image_url:"",emoji:"⚡"},{word:"Sound Waves",phonetic:"",meaning:"The longitudinal waves responsible for sound. They require a medium to travel through and are transmitted by the vibrations of the medium’s particles.",example:"声波",image_url:"",emoji:"⚡"},{word:"Specular Reflection",phonetic:"",meaning:"The reflection of a wave from a smooth surface.",example:"镜面反射",image_url:"",emoji:"⚡"},{word:"Speed of EM Waves",phonetic:"",meaning:"All electromagnetic waves travel at the same speed in a vacuum (3 x 10⁸ m/s).",example:"电磁波速度",image_url:"",emoji:"⚡"},{word:"Time Period",phonetic:"",meaning:"The time it takes for one complete wave to pass a given point. It is the inverse of frequency.",example:"周期",image_url:"",emoji:"⚡"},{word:"Total Internal Reflection",phonetic:"",meaning:"The process of all a wave being reflected when it meets a boundary. It occurs when the angle of incidence is greater than the critical angle, and only when going from a higher refractive index to a lower one.",example:"全内反射",image_url:"",emoji:"⚡"},{word:"Transverse Waves",phonetic:"",meaning:"Waves with oscillations that are perpendicular to the direction of travel/energy transfer.",example:"横波",image_url:"",emoji:"⚡"},{word:"Ultrasound Waves",phonetic:"",meaning:"Waves that have a frequency higher than the upper limit of human hearing (20kHz).",example:"超声波",image_url:"",emoji:"⚡"},{word:"Ultraviolet",phonetic:"",meaning:"Used in energy efficient lamps, disinfecting water, and for sun tanning. It can cause cell and eye damage that can result in skin cancer and eye conditions.",example:"紫外线",image_url:"",emoji:"⚡"},{word:"Virtual Image",phonetic:"",meaning:"An image produced by the apparent, but not actual, divergence of light-rays. Virtual images cannot be projected onto a screen.",example:"虚像",image_url:"",emoji:"⚡"},{word:"Visible Light",phonetic:"",meaning:"The only type of electromagnetic radiation that our eyes can detect. It is used for fibre optic communications and photography.",example:"可见光",image_url:"",emoji:"⚡"},{word:"Wave Velocity",phonetic:"",meaning:"The velocity at which energy is transferred through the medium. It is equal to the product of the wave’s wavelength and frequency.",example:"波速",image_url:"",emoji:"⚡"},{word:"Wave",phonetic:"",meaning:"A process of energy transfer through oscillations, without matter being transferred with it.",example:"波",image_url:"",emoji:"⚡"},{word:"Wavefront",phonetic:"",meaning:"An imaginary surface representing points of a wave that are at the same point in their cycle.",example:"波前",image_url:"",emoji:"⚡"},{word:"Wavelength",phonetic:"",meaning:"The distance from a point on one wave to the same point on the adjacent wave (ie. peak to peak or trough to trough).",example:"波长",image_url:"",emoji:"⚡"},{word:"X-Rays",phonetic:"",meaning:"Used for medical imaging and security scanners. They can cause cell damage and mutations.",example:"X射线",image_url:"",emoji:"⚡"}]},{key:"edexcel-phy-topic4",name:"Edexcel物理 · Topic 4 能源与能量转移",description:"Energy Resources and Energy Transfers · Edexcel IGCSE 物理 · 27 个术语定义",words:[{word:"Chemical Energy",phonetic:"",meaning:"A store of energy found in things such as batteries, fuels and food.",example:"化学能",image_url:"",emoji:"⚡"},{word:"Closed System",phonetic:"",meaning:"A system that experiences no net change in its total energy when energy transfers occur within it.",example:"封闭系统",image_url:"",emoji:"⚡"},{word:"Conduction",phonetic:"",meaning:"The transfer of heat energy through the vibrations of particles in a medium.",example:"热传导",image_url:"",emoji:"⚡"},{word:"Conservation of Energy",phonetic:"",meaning:"The law that energy can be transferred, stored or dissipated but never created or destroyed.",example:"能量守恒",image_url:"",emoji:"⚡"},{word:"Constant Temperature",phonetic:"",meaning:"Bodies at a fixed temperature radiate the same average power that they absorb.",example:"恒温",image_url:"",emoji:"⚡"},{word:"Convection",phonetic:"",meaning:"The transfer of heat energy through convection currents in a fluid.",example:"对流",image_url:"",emoji:"⚡"},{word:"Elastic Potential Energy",phonetic:"",meaning:"The store of energy that stretched or compressed objects contain.",example:"弹性势能",image_url:"",emoji:"⚡"},{word:"Electrostatic Potential Energy",phonetic:"",meaning:"The store of energy due to the relative position of a charge in an electric field.",example:"静电势能",image_url:"",emoji:"⚡"},{word:"Fossil Fuels",phonetic:"",meaning:"Coal, oil and gas.",example:"化石燃料",image_url:"",emoji:"⚡"},{word:"Gravitational Potential Energy",phonetic:"",meaning:"The store of energy that all raised matter has. It is directly proportional to the mass of the object, the distance that it is raised, and the gravitational field strength at that point.",example:"重力势能",image_url:"",emoji:"⚡"},{word:"Heat Transfer",phonetic:"",meaning:"The transfer of thermal energy from a hotter region to a cooler region, through conduction, convection or radiation.",example:"热传递",image_url:"",emoji:"⚡"},{word:"Joule",phonetic:"",meaning:"The unit used for energy. Equal to the work done when a force of one Newton acts over a distance of one metre.",example:"焦耳",image_url:"",emoji:"⚡"},{word:"Kinetic Energy",phonetic:"",meaning:"The store of energy that all moving matter has. It is directly proportional to the object’s mass and to the square of its velocity.",example:"动能",image_url:"",emoji:"⚡"},{word:"Lubrication",phonetic:"",meaning:"The application of a lubricant (such as oil) to reduce the friction that acts between surfaces. This may improve the efficiency of a system.",example:"润滑",image_url:"",emoji:"⚡"},{word:"Magnetic Energy",phonetic:"",meaning:"The potential energy of a magnet.",example:"磁能",image_url:"",emoji:"⚡"},{word:"Non-Renewable Energy Resource",phonetic:"",meaning:"An energy resource that cannot be replenished whilst it is being used. It is a finite resource.",example:"不可再生能源",image_url:"",emoji:"⚡"},{word:"Nuclear Energy",phonetic:"",meaning:"The store of energy found in the nuclei of atoms.",example:"核能",image_url:"",emoji:"⚡"},{word:"Power",phonetic:"",meaning:"The rate at which energy is transferred, or the rate at which work is done. It is calculated by dividing the work done by the time taken.",example:"功率",image_url:"",emoji:"⚡"},{word:"Radiation",phonetic:"",meaning:"The transfer of energy, without the transfer of matter. No medium is needed for radiation to occur.",example:"辐射",image_url:"",emoji:"⚡"},{word:"Renewable Energy Resource",phonetic:"",meaning:"An energy resource that can be replenished whilst it is being used.",example:"可再生能源",image_url:"",emoji:"⚡"},{word:"Sankey Diagram",phonetic:"",meaning:"A diagram used to show the energy transfers of a system.",example:"桑基图",image_url:"",emoji:"⚡"},{word:"Surface Temperature",phonetic:"",meaning:"The temperature of a body is determined by the rate at which they absorb and emit radiation.",example:"表面温度",image_url:"",emoji:"⚡"},{word:"Thermal Energy",phonetic:"",meaning:"The store of energy that all objects with a temperature contain. The higher the temperature, the greater its thermal energy store.",example:"热能",image_url:"",emoji:"⚡"},{word:"Thermal Insulation",phonetic:"",meaning:"The addition of a material that reduces the amount of heat that is transferred from a system to its surroundings.",example:"隔热",image_url:"",emoji:"⚡"},{word:"Useful Energy Transfer",phonetic:"",meaning:"The transfer of energy by a system, to directly serve the purpose of the system.",example:"有用能量转移",image_url:"",emoji:"⚡"},{word:"Waste Energy Transfer",phonetic:"",meaning:"The transfer of energy by a system to a form that doesn’t directly serve the purpose of the system.",example:"无用能量转移",image_url:"",emoji:"⚡"},{word:"Work Done",phonetic:"",meaning:"Work is done on an object when a force causes it to move through a distance. It is equal to the product of the distance travelled and the magnitude of the force in the direction of motion.",example:"做功",image_url:"",emoji:"⚡"}]},{key:"edexcel-phy-topic5",name:"Edexcel物理 · Topic 5 固体、液体与气体",description:"Solids, Liquids and Gases · Edexcel IGCSE 物理 · 23 个术语定义",words:[{word:"Absolute Zero",phonetic:"",meaning:"The lowest possible temperature. At this temperature the particles have no kinetic energy and so are completely stationary.",example:"绝对零度",image_url:"",emoji:"⚡"},{word:"Change in Thermal Energy",phonetic:"",meaning:"The product of the mass, specific heat capacity and temperature change of a substance.",example:"热能变化",image_url:"",emoji:"⚡"},{word:"Chemical Changes",phonetic:"",meaning:"Changes to the chemical structure of a substance. The substance does not usually restore its original properties when the changes are reversed.",example:"化学变化",image_url:"",emoji:"⚡"},{word:"Condensation",phonetic:"",meaning:"The changing from vapour state to a liquid state, when a substance is cooled.",example:"凝结",image_url:"",emoji:"⚡"},{word:"Density",phonetic:"",meaning:"The mass per unit volume of an object.",example:"密度",image_url:"",emoji:"⚡"},{word:"Evaporation",phonetic:"",meaning:"The changing from liquid state to a vapour state, when a substance is heated.",example:"蒸发",image_url:"",emoji:"⚡"},{word:"Freezing",phonetic:"",meaning:"The changing from a liquid state to a solid state, when a substance is cooled.",example:"凝固",image_url:"",emoji:"⚡"},{word:"Gas Temperature",phonetic:"",meaning:"The absolute temperature of a gas is directly proportional to the average kinetic energy of its molecules.",example:"气体温度",image_url:"",emoji:"⚡"},{word:"Gas",phonetic:"",meaning:"A state of matter in which the particles are spread apart and have high kinetic energies. Any intermolecular forces acting between the particles are very weak.",example:"气体",image_url:"",emoji:"⚡"},{word:"Internal Energy",phonetic:"",meaning:"The energy stored by the atoms and molecules that make up a system. It is equal to the sum of the total kinetic and potential energies of the particles in the system.",example:"内能",image_url:"",emoji:"⚡"},{word:"Kelvin",phonetic:"",meaning:"The SI unit of temperature, based on an absolute temperature scale. To convert from degrees Celsius to degrees Kelvin, subtract 273 degrees. For a gas it is proportional to the average kinetic energy of the molecules.",example:"开尔文",image_url:"",emoji:"⚡"},{word:"Liquid",phonetic:"",meaning:"A state of matter in which the particles are in contact, but can flow over each other. Intermolecular forces act between the particles.",example:"液体",image_url:"",emoji:"⚡"},{word:"Melting",phonetic:"",meaning:"The changing from solid state to liquid state, when a substance is heated.",example:"熔化",image_url:"",emoji:"⚡"},{word:"Pascals",phonetic:"",meaning:"The unit of pressure, equal to a force of one Newton acting perpendicular to an area of one metre squared.",example:"帕斯卡",image_url:"",emoji:"⚡"},{word:"Physical Changes",phonetic:"",meaning:"Changes to the physical properties of a substance which can be reversed. Changes of state are physical changes since substances can restore their original properties when the changes are reversed.",example:"物理变化",image_url:"",emoji:"⚡"},{word:"Pressure in a Liquid Column",phonetic:"",meaning:"Equal to the product of the height of the column, the density of the liquid and the gravitational field strength.",example:"液柱压强",image_url:"",emoji:"⚡"},{word:"Pressure of a Gas",phonetic:"",meaning:"The perpendicular force per unit area acting on the surfaces of a container as a result of the gas particles colliding with it. It acts equally in all directions.",example:"气体压强",image_url:"",emoji:"⚡"},{word:"Pressure",phonetic:"",meaning:"The force acting perpendicular to a surface, per unit area.",example:"压强",image_url:"",emoji:"⚡"},{word:"Pressure-Volume Relationship",phonetic:"",meaning:"When at a constant temperature, the volume of a fixed quantity of gas is inversely proportional to its pressure.",example:"压强-体积关系",image_url:"",emoji:"⚡"},{word:"Pressure-Temperature Relationship",phonetic:"",meaning:"When at a constant volume, the pressure of a fixed quantity of gas is directly proportional to its absolute temperature.",example:"压强-温度关系",image_url:"",emoji:"⚡"},{word:"Solid",phonetic:"",meaning:"A state of matter in which the particles are tightly packed together and can only vibrate about their fixed positions. Strong intermolecular forces act between the particles",example:"固体",image_url:"",emoji:"⚡"},{word:"Specific Heat Capacity",phonetic:"",meaning:"The amount of energy needed to increase the temperature of one kilogram of a given substance by one degree Celsius.",example:"比热容",image_url:"",emoji:"⚡"},{word:"Temperature",phonetic:"",meaning:"A measure of the average kinetic energy of the particles in a substance. An increase in temperature will result in an increase in the particles’ kinetic energies and velocities.",example:"温度",image_url:"",emoji:"⚡"}]},{key:"edexcel-phy-topic6",name:"Edexcel物理 · Topic 6 磁学与电磁学",description:"Magnetism and Electromagnetism · Edexcel IGCSE 物理 · 23 个术语定义",words:[{word:"Current-Carrying Wires",phonetic:"",meaning:"When current flows through a wire, a magnetic field is generated around it. The strength of the field depends on the magnitude of the current and the distance from the wire.",example:"载流导线",image_url:"",emoji:"⚡"},{word:"Electric Motor",phonetic:"",meaning:"A current-carrying coil of wire in a magnetic field. The two sides of the coil that are perpendicular to the magnetic field experience forces in opposite directions, causing rotation.",example:"电动机",image_url:"",emoji:"⚡"},{word:"Electromagnet",phonetic:"",meaning:"A solenoid with an iron core. The magnetism of an electromagnet can be switched on and off, and the strength changed, through varying the current in the solenoid.",example:"电磁铁",image_url:"",emoji:"⚡"},{word:"Fleming’s Left-Hand Rule",phonetic:"",meaning:"A rule used to determine the orientation of the force (thumb), current (second finger) and magnetic field (first finger) when a current-carrying wire is placed in a magnetic field (motor effect).",example:"弗莱明左手定则",image_url:"",emoji:"⚡"},{word:"Generator Effect",phonetic:"",meaning:"When there is relative motion between an electrical conductor and a magnetic field, a voltage will be induced across the ends of the conductor. A current will flow if this conductor is part of a complete circuit.",example:"发电机效应",image_url:"",emoji:"⚡"},{word:"Induced Magnet",phonetic:"",meaning:"A material that becomes a magnet when it is placed in an existing magnetic field, but loses its magnetism quickly once it is removed. Induced magnetism always produces attractive forces.",example:"感应磁体",image_url:"",emoji:"⚡"},{word:"Like Magnetic Poles",phonetic:"",meaning:"When matching poles of a magnet are brought near each other they repel each other.",example:"同名磁极",image_url:"",emoji:"⚡"},{word:"Loudspeaker",phonetic:"",meaning:"A device that converts variations in current into vibrations of a diaphragm to produce corresponding sound waves.",example:"扬声器",image_url:"",emoji:"⚡"},{word:"Magnetic Field Lines",phonetic:"",meaning:"Lines that show the strength and direction of a magnetic field. The lines point from North to South and their concentration represents the magnitude of the field.",example:"磁感线",image_url:"",emoji:"⚡"},{word:"Magnetic Field",phonetic:"",meaning:"The region around a magnet in which another magnet or magnetic material will experience a non-contact force.",example:"磁场",image_url:"",emoji:"⚡"},{word:"Magnetic Materials",phonetic:"",meaning:"Iron, steel, cobalt and nickel.",example:"磁性材料",image_url:"",emoji:"⚡"},{word:"Magnetic Poles",phonetic:"",meaning:"The regions of a magnet where the magnetic forces are at their strongest.",example:"磁极",image_url:"",emoji:"⚡"},{word:"Magnetically Hard",phonetic:"",meaning:"A material property that means the material can be permanently magnetised. Examples include iron and alloys containing large amounts of iron.",example:"硬磁材料",image_url:"",emoji:"⚡"},{word:"Magnetically Soft",phonetic:"",meaning:"A material property that means the material can be temporarily magnetised. Examples include alloys with lower amounts of iron.",example:"软磁材料",image_url:"",emoji:"⚡"},{word:"Permanent Magnet",phonetic:"",meaning:"A magnet that produces its own magnetic field.",example:"永磁体",image_url:"",emoji:"⚡"},{word:"Power Cables",phonetic:"",meaning:"Metal wires that are part of the National Grid. Electricity is transported along them at very high voltages to reduce the energy loss and make the transportation more efficient.",example:"电力电缆",image_url:"",emoji:"⚡"},{word:"Solenoid",phonetic:"",meaning:"A wire wrapped into the shape of a coil, that has a strong and uniform magnetic field inside of it. The solenoid’s magnetic field strength can be increased by adding an iron core.",example:"螺线管",image_url:"",emoji:"⚡"},{word:"Step-Down Transformer",phonetic:"",meaning:"A transformer that has a smaller potential difference in the secondary coil than in the primary coil. This is a result of the secondary coil having fewer turns.",example:"降压变压器",image_url:"",emoji:"⚡"},{word:"Step-Up Transformer",phonetic:"",meaning:"A transformer that has a larger potential difference in the secondary coil than in the primary coil. This is a result of the secondary coil having more turns.",example:"升压变压器",image_url:"",emoji:"⚡"},{word:"Transformer",phonetic:"",meaning:"An iron core with a primary and secondary coil of wire wound around opposite ends. Transformers can change the magnitude of an alternating voltage.",example:"变压器",image_url:"",emoji:"⚡"},{word:"Turns Ratio",phonetic:"",meaning:"The number of turns in the primary coil of a transformer over the number of turns in the secondary coil. This is equal to the voltage ratio for a 100% efficient transformer.",example:"匝数比",image_url:"",emoji:"⚡"},{word:"Unlike Magnetic Poles",phonetic:"",meaning:"When opposite poles of a magnet are brought near each other they attract each other.",example:"异名磁极",image_url:"",emoji:"⚡"},{word:"Voltage Ratio",phonetic:"",meaning:"The voltage across the primary coil of a transformer over the voltage across the secondary coil.",example:"电压比",image_url:"",emoji:"⚡"}]},{key:"edexcel-phy-topic7",name:"Edexcel物理 · Topic 7 放射性与粒子",description:"Radioactivity and Particles · Edexcel IGCSE 物理 · 34 个术语定义",words:[{word:"Activity",phonetic:"",meaning:"The rate at which an unstable nucleus decays. The activity of a radioactive source reduces over time.",example:"放射性活度",image_url:"",emoji:"⚡"},{word:"Alpha Particle",phonetic:"",meaning:"A positively charged particle consisting of two protons and two neutrons. They are highly ionising, but can be stopped by a few centimetres of air.",example:"α粒子",image_url:"",emoji:"⚡"},{word:"Atomic Number",phonetic:"",meaning:"The number of protons found in an atom of a specific element. Each element has a different atomic number.",example:"原子序数",image_url:"",emoji:"⚡"},{word:"Background Radiation",phonetic:"",meaning:"Radiation that is found in small quantities all around us and originates from natural sources such as rocks and cosmic rays, as well as from man-made sources such as nuclear weapons testing and accidents.",example:"背景辐射",image_url:"",emoji:"⚡"},{word:"Becquerel",phonetic:"",meaning:"The unit of radioactive activity.",example:"贝可勒尔",image_url:"",emoji:"⚡"},{word:"Beta Particle",phonetic:"",meaning:"A high speed electron that a nucleus emits when a neutron converts into a proton. They are ionising but can be stopped by a thin sheet of aluminium.",example:"β粒子",image_url:"",emoji:"⚡"},{word:"Chain Reaction",phonetic:"",meaning:"The process of neutrons released by a fission reaction, being absorbed by another unstable, large nuclei, and inducing further fission.",example:"链式反应",image_url:"",emoji:"⚡"},{word:"Control Rods",phonetic:"",meaning:"Found in nuclear reactors to control the rate of fission. They absorb neutrons, preventing them from inducing further fission reactions.",example:"控制棒",image_url:"",emoji:"⚡"},{word:"Electrons",phonetic:"",meaning:"A negatively charged constituent of the atom, that are found in different energy levels, around the nucleus.",example:"电子",image_url:"",emoji:"⚡"},{word:"Energy Levels",phonetic:"",meaning:"The stable states in which electrons are found in around a nucleus. Electrons can transition to a higher energy level through the absorption of electromagnetic radiation and can transition to a lower energy level through the emission of electromagnetic radiation.",example:"能级",image_url:"",emoji:"⚡"},{word:"Fission Products",phonetic:"",meaning:"Fission produces two smaller nuclei, two or three neutrons and gamma rays. These products are released with kinetic energy.",example:"裂变产物",image_url:"",emoji:"⚡"},{word:"Gamma Ray",phonetic:"",meaning:"Electromagnetic radiation emitted from a nucleus. They have a very high penetrating power and require several centimetre of lead to absorb them.",example:"γ射线",image_url:"",emoji:"⚡"},{word:"Geiger-Muller Tube",phonetic:"",meaning:"A device used to detect ionising radiation.",example:"盖革-米勒计数管",image_url:"",emoji:"⚡"},{word:"Half-Life",phonetic:"",meaning:"The time it takes for the number of unstable nuclei of an isotope in a sample to halve, or the time it takes for the initial count rate of a sample of the isotope to halve. It is different for different isotopes.",example:"半衰期",image_url:"",emoji:"⚡"},{word:"Ions",phonetic:"",meaning:"Atoms with a resultant charge due to the loss or gain of electrons.",example:"离子",image_url:"",emoji:"⚡"},{word:"Ionising Radiation",phonetic:"",meaning:"Radiation that can cause cell mutations, damage cells and tissues, and lead to cancers.",example:"电离辐射",image_url:"",emoji:"⚡"},{word:"Irradiation",phonetic:"",meaning:"The process of an object being exposed to nuclear radiation. The object doesn’t become radioactive.",example:"辐照",image_url:"",emoji:"⚡"},{word:"Isotopes",phonetic:"",meaning:"Atoms with the same number of protons but different numbers of neutrons. The atomic number is the same, but the mass number is different.",example:"同位素",image_url:"",emoji:"⚡"},{word:"Mass Number",phonetic:"",meaning:"The number of protons and neutrons in an atom.",example:"质量数",image_url:"",emoji:"⚡"},{word:"Mass-Energy Equivalence",phonetic:"",meaning:"All matter has an associated energy. This means that mass can be converted into energy in the form of radiation.",example:"质能等价",image_url:"",emoji:"⚡"},{word:"Moderator",phonetic:"",meaning:"A substance found in nuclear reactors to slow down neutrons so they are at suitable speeds to induce fission in fissile nuclei.",example:"慢化剂",image_url:"",emoji:"⚡"},{word:"Negative Ions",phonetic:"",meaning:"Atoms that gained electrons and so have a resultant negative charge.",example:"负离子",image_url:"",emoji:"⚡"},{word:"Neutrons",phonetic:"",meaning:"A neutrally charged constituent of the nucleus.",example:"中子",image_url:"",emoji:"⚡"},{word:"Nuclear Fission",phonetic:"",meaning:"The splitting of a large and unstable nucleus into two smaller and more stable nuclei to produce energy. This is the method currently used in nuclear power stations.",example:"核裂变",image_url:"",emoji:"⚡"},{word:"Nuclear Fusion",phonetic:"",meaning:"The joining of two small, light nuclei to form a larger, heavier one and release energy. It cannot happen at low pressures and temperatures since in these conditions the electrostatic repulsion of protons in the nucleus cannot be overcome.",example:"核聚变",image_url:"",emoji:"⚡"},{word:"PET Scanner",phonetic:"",meaning:"A medical imaging device that uses radioactive tracers and detectors to form internal body images.",example:"PET扫描仪",image_url:"",emoji:"⚡"},{word:"Photographic Film",phonetic:"",meaning:"A material that reacts to ionising radiation, allowing an image to be formed.",example:"感光胶片",image_url:"",emoji:"⚡"},{word:"Positive Ions",phonetic:"",meaning:"Atoms that have lost electrons and so have a resultant positive charge.",example:"正离子",image_url:"",emoji:"⚡"},{word:"Protons",phonetic:"",meaning:"A positively charged constituent of the nucleus.",example:"质子",image_url:"",emoji:"⚡"},{word:"Radioactive Contamination",phonetic:"",meaning:"The unwanted presence of radioactive atoms on other materials. It is hazardous due to the decay of the contaminating atoms.",example:"放射性污染",image_url:"",emoji:"⚡"},{word:"Radioactive Decay",phonetic:"",meaning:"The random process involving unstable nuclei emitting radiation to become more stable.",example:"放射性衰变",image_url:"",emoji:"⚡"},{word:"Random Nature of Radioactive Decay",phonetic:"",meaning:"You cannot predict which nuclei in a radioactive sample will decay next, or when the next decay will occur - it is a random process.",example:"放射性衰变的随机性",image_url:"",emoji:"⚡"},{word:"Shielding",phonetic:"",meaning:"A barrier used to prevent radioactive daughter products leaving a nuclear reactor.",example:"屏蔽",image_url:"",emoji:"⚡"},{word:"Uranium-235",phonetic:"",meaning:"The radioactive isotope used in nuclear reactors. It is often referred to as U-235.",example:"铀-235",image_url:"",emoji:"⚡"}]},{key:"edexcel-phy-topic8",name:"Edexcel物理 · Topic 8 天体物理",description:"Astrophysics · Edexcel IGCSE 物理 · 25 个术语定义",words:[{word:"Artificial Satellites",phonetic:"",meaning:"Man-made satellites that have been sent into space for purposes such as satellite imaging and communications.",example:"人造卫星",image_url:"",emoji:"⚡"},{word:"Big Bang Theory",phonetic:"",meaning:"The currently accepted model for the origin of the universe. It suggests that the universe has expanded from an initially very small, hot and dense point.",example:"大爆炸理论",image_url:"",emoji:"⚡"},{word:"Circular Orbits",phonetic:"",meaning:"The circular path that a satellite or planet may travel in. Since their direction is continually changing, their velocity is always changing. Gravity provides the required force for these orbits.",example:"圆形轨道",image_url:"",emoji:"⚡"},{word:"CMBR",phonetic:"",meaning:"Cosmic microwave background radiation. This is electromagnetic radiation that is found in small quantities all around us. It is suggested to have come from the high energy radiation emitted by the Big Bang.",example:"宇宙微波背景辐射",image_url:"",emoji:"⚡"},{word:"Comets",phonetic:"",meaning:"Objects consisting of rock, dust and ice that travel in the universe at high speeds. When they approach the sun they vaporise and produce a trail.",example:"彗星",image_url:"",emoji:"⚡"},{word:"Doppler Effect",phonetic:"",meaning:"The change in a wave’s observed wavelength and frequency when there is relative motion between its source and an observer.",example:"多普勒效应",image_url:"",emoji:"⚡"},{word:"Galaxy",phonetic:"",meaning:"A system containing billions of stars.",example:"星系",image_url:"",emoji:"⚡"},{word:"Hertzsprung-Russell Diagram",phonetic:"",meaning:"A plot of the luminosity of stars against their temperatures.",example:"赫罗图",image_url:"",emoji:"⚡"},{word:"Main Sequence Star",phonetic:"",meaning:"The stable state of all stars. The gravitational forces pulling the star together, and the pressure pushing outwards, are balanced.",example:"主序星",image_url:"",emoji:"⚡"},{word:"Milky Way Galaxy",phonetic:"",meaning:"The galaxy in which our solar system is located.",example:"银河系",image_url:"",emoji:"⚡"},{word:"Natural Satellites",phonetic:"",meaning:"The moons that orbit planets.",example:"天然卫星",image_url:"",emoji:"⚡"},{word:"Nebula",phonetic:"",meaning:"A cloud of dust and gas.",example:"星云",image_url:"",emoji:"⚡"},{word:"Orbital Radius",phonetic:"",meaning:"The radius of a body’s orbit. For a stable orbit, a change in its orbital radius is required for the body to undergo a speed change.",example:"轨道半径",image_url:"",emoji:"⚡"},{word:"Orbital Speed",phonetic:"",meaning:"A measure of how fast an object orbits. It is directly proportional to the orbital radius and inversely proportional to the orbital period.",example:"轨道速度",image_url:"",emoji:"⚡"},{word:"Orbital Period",phonetic:"",meaning:"The time it takes for an object in orbit to complete one full cycle.",example:"轨道周期",image_url:"",emoji:"⚡"},{word:"Planet",phonetic:"",meaning:"A body that has a sufficiently large mass and that orbits a star. Our solar system contains eight planets, all of which orbit the sun.",example:"行星",image_url:"",emoji:"⚡"},{word:"Protostar",phonetic:"",meaning:"The first stage all stars go through after forming from a nebula. In this stage the star becomes hot enough for hydrogen nuclei to fuse.",example:"原恒星",image_url:"",emoji:"⚡"},{word:"Red Giant Star",phonetic:"",meaning:"When their hydrogen is used up and larger nuclei are produced by fusion, stars of a similar magnitude to the Sun will expand to form a red giant.",example:"红巨星",image_url:"",emoji:"⚡"},{word:"Red-Shift",phonetic:"",meaning:"The observed increase in the wavelength of the light emitted by distant galaxies. The more distant the galaxy, the faster it is moving and so the bigger the observed increase in wavelength.",example:"红移",image_url:"",emoji:"⚡"},{word:"Star Life Cycle",phonetic:"",meaning:"The stages that a star passes through in its lifetime, dependent on the size of the star relative to the sun.",example:"恒星生命周期",image_url:"",emoji:"⚡"},{word:"Sun",phonetic:"",meaning:"A star formed from a cloud of dust and gas being pulled together by gravitational attraction. Fusion reactions occur in the sun.",example:"太阳",image_url:"",emoji:"⚡"},{word:"Supernova",phonetic:"",meaning:"The explosion of a massive star, that distributes the elements created by the fusion reactions in the star, throughout the universe.",example:"超新星",image_url:"",emoji:"⚡"},{word:"Universe",phonetic:"",meaning:"A large system of billions of galaxies.",example:"宇宙",image_url:"",emoji:"⚡"},{word:"Weight",phonetic:"",meaning:"The force of matter due to gravity. It is equal to the product of mass and gravitational field strength, and so varies depending on your location in the universe.",example:"重力",image_url:"",emoji:"⚡"},{word:"White Dwarf",phonetic:"",meaning:"When the fusion reactions in stars of a similar magnitude to the sun come to an end, the star will contract under gravity and cool down to form a white dwarf.",example:"白矮星",image_url:"",emoji:"⚡"}]}];export{e as EDEXCEL_PHYSICS_BANKS};
